/**
 * Cross-SDK XDR serialization tests.
 *
 * Reads vectors generated by the Rust SDK's `groundhog-test-vectors xdr`
 * and verifies the TypeScript XDR encoding produces identical bytes.
 */
import { describe, it, expect } from "vitest";
import { XdrWriter, serialize, OptionCodec, VarArrayCodec } from "../../src/index.js";
import { toHex, fromHex } from "../../src/utils/index.js";
import {
  contractAddress, sha256Hash, ed25519PublicKey, contractEntrypointID,
  StorageKeyType, codec,
} from "../../src/protocol/index.js";
import type { Invocation, Transaction, Uniquifier } from "../../src/protocol/index.js";
import { existsSync, readFileSync } from "fs";

const VECTORS_PATH = "test/fixtures/xdr_vectors.json";

interface XdrVector {
  name: string;
  type: string | { bytes?: string; string?: string; vec?: string; option?: string };
  value: unknown;
  expected_hex: string;
}

interface VectorFile {
  version: number;
  category: string;
  vectors: XdrVector[];
}

import type { XdrCodec } from "../../src/index.js";

const primitiveCodecs: Record<string, XdrCodec<bigint>> = {
  u32: { encode(w, v) { w.writeUint32(v); }, decode(r) { return r.readUint32(); } },
  i32: { encode(w, v) { w.writeInt32(v); }, decode(r) { return r.readInt32(); } },
  u64: { encode(w, v) { w.writeUint64(v); }, decode(r) { return r.readUint64(); } },
  i64: { encode(w, v) { w.writeInt64(v); }, decode(r) { return r.readInt64(); } },
  u128: { encode(w, v) { w.writeUint128(v); }, decode(r) { return r.readUint128(); } },
  i128: { encode(w, v) { w.writeInt128(v); }, decode(r) { return r.readInt128(); } },
};

function encodePrimitive(type: string, value: unknown): Uint8Array {
  const w = new XdrWriter();
  switch (type) {
    case "u32": w.writeUint32(BigInt(value as string)); break;
    case "i32": w.writeInt32(BigInt(value as string)); break;
    case "u64": w.writeUint64(BigInt(value as string)); break;
    case "i64": w.writeInt64(BigInt(value as string)); break;
    case "u128": w.writeUint128(BigInt(value as string)); break;
    case "i128": w.writeInt128(BigInt(value as string)); break;
    case "bool": w.writeBool(value as boolean); break;
    default: return null!;
  }
  return w.finish();
}

function encodeCollection(type: { bytes?: string; string?: string; vec?: string; option?: string }, value: unknown): Uint8Array {
  const w = new XdrWriter();
  if (type.bytes) {
    const data = typeof value === "string" ? fromHex(value as string) : new Uint8Array(0);
    w.writeVarOpaque(data, parseInt(type.bytes));
  } else if (type.string) {
    w.writeString(value as string, parseInt(type.string));
  } else if (type.vec) {
    return serialize(
      (value as string[]).map(v => BigInt(v)),
      VarArrayCodec(primitiveCodecs[type.vec], 0xFFFFFFFF),
    );
  } else if (type.option) {
    return serialize(
      value === null ? null : BigInt(value as string),
      OptionCodec(primitiveCodecs[type.option]),
    );
  } else {
    return null!;
  }
  return w.finish();
}

function encodeFixed(type: string, value: string): Uint8Array {
  switch (type) {
    case "ContractAddress":
      return serialize(contractAddress(fromHex(value)), codec.ContractAddress);
    case "SHA256Hash":
      return serialize(sha256Hash(fromHex(value)), codec.SHA256Hash);
    case "Ed25519PublicKey":
      return serialize(ed25519PublicKey(fromHex(value)), codec.Ed25519PublicKey);
    case "ContractEntrypointID":
      return serialize(contractEntrypointID(fromHex(value)), codec.ContractEntrypointID);
    default:
      return null!;
  }
}

describe("cross-SDK: XDR serialization", () => {
  if (!existsSync(VECTORS_PATH)) {
    it.skip(`no vectors file at ${VECTORS_PATH} (run groundhog-test-vectors xdr to generate)`, () => {});
    return;
  }

  const data: VectorFile = JSON.parse(readFileSync(VECTORS_PATH, "utf-8"));

  for (const vec of data.vectors) {
    it(`matches Rust SDK: ${vec.name}`, () => {
      let encoded: Uint8Array;

      if (typeof vec.type === "string") {
        // Primitive or protocol type
        const primitives = ["u32", "i32", "u64", "i64", "u128", "i128", "bool"];
        const fixedTypes = ["ContractAddress", "SHA256Hash", "Ed25519PublicKey", "ContractEntrypointID"];

        if (primitives.includes(vec.type)) {
          encoded = encodePrimitive(vec.type, vec.value);
        } else if (fixedTypes.includes(vec.type)) {
          encoded = encodeFixed(vec.type, vec.value as string);
        } else if (vec.type === "StorageKeyType") {
          const { variant } = vec.value as { variant: string };
          const disc = StorageKeyType[variant as keyof typeof StorageKeyType];
          if (disc === undefined) {
            throw new Error(`Unknown StorageKeyType variant "${variant}" — protocol version mismatch?`);
          }
          encoded = serialize(disc, codec.StorageKeyType);
        } else {
          // Skip complex struct types for now — they need custom construction
          return;
        }
      } else {
        encoded = encodeCollection(vec.type, vec.value);
      }

      if (!encoded) {
        // Unsupported vector type, skip
        return;
      }

      expect(toHex(encoded)).toBe(vec.expected_hex);
    });
  }
});
